def encode(message):
    vowels = 'aeiouAEIOU'
    result = []

    for char in message:
        if char.isalpha():
            # Swap case
            swapped_char = char.lower() if char.isupper() else char.upper()

            # Replace vowels with letter 2 places ahead
            if swapped_char in vowels:
                index = ord(swapped_char)
                shifted = index + 2
                # Handle wrap-around for 'y' and 'z'
                if swapped_char.islower() and shifted > ord('z'):
                    shifted = shifted - 26
                elif swapped_char.isupper() and shifted > ord('Z'):
                    shifted = shifted - 26
                swapped_char = chr(shifted)

            result.append(swapped_char)
        else:
            result.append(char)

    return ''.join(result)
```

