def fix_spaces(text):
    result = ""
    i = 0
    while i < len(text):
        if text[i] == ' ':
            # Count consecutive spaces
            space_count = 0
            j = i
            while j < len(text) and text[j] == ' ':
                space_count += 1
                j += 1

            # Replace based on count
            if space_count > 2:
                result += '-'
            else:
                result += '_' * space_count

            i = j
        else:
            result += text[i]
            i += 1
    return result
```

