def search(nums):
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        # Check if mid is even or odd
        if mid % 2 == 1:
            mid -= 1  # Make mid point to the previous even index

        # If the pair is not matching, the single element is on the left
        if nums[mid] != nums[mid + 1]:
            right = mid
        else:
            left = mid + 2

    return nums[left]
```

