def amicable_numbers_sum(n):
    def sum_of_divisors(num):
        total = 1
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                total += i
                if i != num // i:
                    total += num // i
        return total

    amicable_sum = 0
    visited = set()

    for i in range(2, n + 1):
        if i in visited:
            continue
        j = sum_of_divisors(i)
        if j != i and j <= n:
            if sum_of_divisors(j) == i:
                amicable_sum += i + j
                visited.add(i)
                visited.add(j)

    return amicable_sum
```

