def pancake_sort(arr):
    def flip(arr, k):
        left, right = 0, k - 1
        while left < right:
            arr[left], arr[right] = arr[right], arr[left]
            left += 1
            right -= 1

    n = len(arr)
    for i in range(n - 1, 0, -1):
        max_idx = 0
        for j in range(1, i + 1):
            if arr[j] > arr[max_idx]:
                max_idx = j

        if max_idx != i:
            flip(arr, max_idx + 1)
            flip(arr, i + 1)

    return arr
```

