def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Initialize arrays to store maximum increasing and decreasing sums
    inc = [0] * n
    dec = [0] * n

    # Fill inc array: maximum sum ending at i with increasing sequence
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Fill dec array: maximum sum starting at i with decreasing sequence
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find maximum sum of bitonic subsequence
    max_sum = 0
    for i in range(n):
        # The bitonic sequence has peak at i
        # Sum = increasing part ending at i + decreasing part starting at i - arr[i] (to avoid double counting)
        total = inc[i] + dec[i] - arr[i]
        max_sum = max(max_sum, total)

    return max_sum
```

