import math

def babylonian_squareroot(n):
    if n < 0:
        raise ValueError("Cannot compute square root of a negative number")
    if n == 0 or n == 1:
        return n

    x = n
    while True:
        root = 0.5 * (x + n / x)
        if abs(root - x) < 0.001:
            break
        x = root
    return root
