```python
def max_sub_array_sum_repeated(arr, n, k):
    # Handle the case where all elements are negative
    if all(x < 0 for x in arr):
        return max(arr)

    # Calculate maximum subarray sum using Kadane's algorithm
    def kadane(arr):
        max_ending_here = max_so_far = arr[0]
        for i in range(1, len(arr)):
            max_ending_here = max(arr[i], max_ending_here + arr[i])
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # If k == 1, just return the max subarray sum of original array
    if k == 1:
        return kadane(arr)

    # Calculate total sum of array
    total_sum = sum(arr)

    # Calculate max prefix sum and max suffix sum
    max_prefix_sum = arr[0]
    current_prefix_sum = 0
    for i in range(n):
        current_prefix_sum += arr[i]
        max_prefix_sum = max(max_prefix_sum, current_prefix_sum)

    max_suffix_sum = arr[n-1]
    current_suffix_sum = 0
    for i in range(n-1, -1, -1):
        current_suffix_sum += arr[i]
        max_suffix_sum = max(max_suffix_sum, current_suffix_sum)

    # If total sum is positive, we can benefit from repeating the array
    if total_sum > 0:
        # The maximum sum will be: max_suffix + (k-2)*total_sum + max_prefix
        return max_suffix_sum + (k - 2) * total_sum + max_prefix_sum
    else:
        # If total sum is not positive, we can't benefit from repeating
        # So we just take the max subarray sum of the doubled array
        doubled_arr = arr + arr
        return kadane(doubled_arr)
```

