```python
def max_sum_increasing_subseq(arr, n, i, k):
    if i >= k or k >= n:
        return 0

    # dp[j] will store the maximum sum of increasing subsequence ending at index j
    dp = [0] * n
    for j in range(n):
        dp[j] = arr[j]

    # Fill dp array
    for j in range(1, n):
        for prev in range(j):
            if arr[prev] < arr[j]:
                dp[j] = max(dp[j], dp[prev] + arr[j])

    # Find maximum sum of increasing subsequence ending at index i
    max_sum_at_i = dp[i]

    # Now find the maximum sum of increasing subsequence that includes arr[k]
    # and has elements from indices 0 to i (inclusive) and then includes arr[k]
    max_sum_with_k = 0
    for j in range(i + 1):
        if arr[j] < arr[k] and dp[j] + arr[k] > max_sum_with_k:
            max_sum_with_k = dp[j] + arr[k]

    # If no valid subsequence ending at i can be extended to include k, return 0
    if max_sum_with_k == 0:
        return 0

    return max_sum_with_k
```

