        return 0
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 2

    p0, p1, p2 = 3, 0, 2
    total = p0 + p1 + p2

    for i in range(3, n + 1):
        p_next = p1 + p0
        total += p_next
        p0, p1, p2 = p1, p2, p_next

    return total
