def min_Swaps(s1, s2):
    if len(s1) != len(s2):
        return "Not Possible"

    count_1s_in_s1 = s1.count('1')
    count_1s_in_s2 = s2.count('1')

    if count_1s_in_s1 != count_1s_in_s2:
        return "Not Possible"

    swaps = 0
    diff_positions = []

    for i in range(len(s1)):
        if s1[i] != s2[i]:
            diff_positions.append(i)

    # Count mismatched positions where s1 has '1' and s2 has '0'
    ones_in_s1 = 0
    for pos in diff_positions:
        if s1[pos] == '1':
            ones_in_s1 += 1

    # Each swap fixes two mismatches: one '1' from s1 to s2 and one '0' from s2 to s1
    # So we need exactly ones_in_s1 swaps
    swaps = ones_in_s1

    return swaps
```

