def find_kth(arr1, arr2, k):
    def find_kth_helper(i, j, k):
        if i >= len(arr1):
            return arr2[j + k - 1]
        if j >= len(arr2):
            return arr1[i + k - 1]
        if k == 1:
            return min(arr1[i], arr2[j])

        mid1 = min(i + k // 2 - 1, len(arr1) - 1)
        mid2 = min(j + k // 2 - 1, len(arr2) - 1)

        if arr1[mid1] <= arr2[mid2]:
            return find_kth_helper(mid1 + 1, j, k - (mid1 - i + 1))
        else:
            return find_kth_helper(i, mid2 + 1, k - (mid2 - j + 1))

    return find_kth_helper(0, 0, k)
```

