def get_median(list1, list2, n):
    # Merge the two sorted lists
    merged = []
    i = j = 0

    while i < n and j < n:
        if list1[i] <= list2[j]:
            merged.append(list1[i])
            i += 1
        else:
            merged.append(list2[j])
            j += 1

    # Add remaining elements
    while i < n:
        merged.append(list1[i])
        i += 1
    while j < n:
        merged.append(list2[j])
        j += 1

    # Find median
    if n % 2 == 1:
        return float(merged[n])
    else:
        return (merged[n-1] + merged[n]) / 2.0
```

