def count_rotation(arr):
    left, right = 0, len(arr) - 1
    n = len(arr)

    while left <= right:
        if arr[left] <= arr[right]:
            return left

        mid = (left + right) // 2

        # Check if mid is the pivot (smallest element)
        if mid > 0 and arr[mid] < arr[mid - 1]:
            return mid

        # Decide which half to search
        if arr[mid] >= arr[left]:
            left = mid + 1
        else:
            right = mid - 1

    return 0
```

